// The prototype's catalogue, one entry per Giant bike category.
//
// Every file under categories/ is generated by scripts/import-category.mjs from
// giant-bicycles.com/gb — including each category's own filter groups, which is what lets
// a road bike offer "Frame Material" while a mountain bike also offers "Suspension" and
// "Battery Capacity". Re-import with `node scripts/import-category.mjs`.
//
// The prototype is set in the Netherlands, so the GB files are re-priced in euros as they are
// loaded (see `toEuroPrice`). The range and the copy are still Giant's GB ones.

import { CURRENCY, MARKET, toEuroPrice } from '../lib/format'

import crossAndGravelBikes from './categories/cross-and-gravel-bikes.json'
import eBikes from './categories/e-bikes.json'
import fitnessAndCityBikes from './categories/fitness-and-city-bikes.json'
import kidsBikes from './categories/kids-bikes.json'
import mountainBikes from './categories/mountain-bikes.json'
import roadBikes from './categories/road-bikes.json'

export type PriceMode = 'regular' | 'discount' | 'from' | 'from-discount'

export interface ProductPrice {
  mode: PriceMode
  amount: string
  /**
   * The reference price the discount is struck against. EU Omnibus (2019/2161) requires
   * this to be the lowest price of the previous 30 days, so that is what it holds.
   */
  oldAmount?: string
  /**
   * The regular selling price, when it is higher than `oldAmount` — i.e. the item was
   * already reduced within the 30 days. Disclosed as a second, separate saving.
   * ponytail: optional and unpopulated — Giant publishes one `oldprice` per build, so the
   * importer has nothing to read it from. Fill it the day a feed carries an RRP.
   */
  regularAmount?: string
}

export interface ProductColor {
  key: string
  label: string
  /** One hex for a solid swatch, two for a split swatch. */
  colors: string[]
  /** [main, hover] — the second image is revealed on card hover. */
  images: string[]
  /** The bike page this colour belongs to, where it differs from the product's own. */
  url?: string
}

/**
 * Giant's own delivery stock, from the per-SKU JSON-LD offers on each model page. This is
 * the one live thing in the catalogue — a re-import on another day will read differently.
 */
export interface ProductStock {
  /** SKUs found (size x colourway). */
  skus: number
  /** How many of them Giant lists as InStock. */
  inStock: number
  /** The sizes at least one in-stock SKU covers, catalogue order. */
  sizes: string[]
}

export interface Product {
  id: string
  /**
   * Distance to the nearest store holding stock, in the importer's miles. Synthesised — see lib/store-stock.
   * ponytail: kept because the importer still emits it; the store row reads store-stock instead.
   */
  availabilityMiles: number
  stock: ProductStock
  title: string
  url: string
  description: string
  price: ProductPrice
  secondary: string
  tag?: { type: 'new' | 'sale' | 'best-seller'; label: string } | null
  award?: { src: string; alt: string }
  /**
   * Giant's own listing facet classes, e.g. `best-for-enduro`, `frame-material-aluminium`.
   * Each filter option is named after one of these, so a filter matches by membership.
   */
  facets: string[]
  sizes: string[]
  colors: ProductColor[]
}

export interface FilterOption {
  id: string
  label: string
  /** Info tooltip copy, shown behind an (i) button. Giant's own, where they publish one. */
  info?: string
}

export interface FilterGroupDefinition {
  id: string
  label: string
  options: FilterOption[]
}

export interface Category {
  slug: string
  title: string
  market: string
  currency: string
  generatedAt: string
  source: string
  filterGroups: FilterGroupDefinition[]
  /** Every frame size offered across the category, smallest first. */
  sizes: string[]
  products: Product[]
}

function euroPrice(price: ProductPrice): ProductPrice {
  return {
    ...price,
    amount: toEuroPrice(price.amount),
    ...(price.oldAmount && { oldAmount: toEuroPrice(price.oldAmount) }),
    ...(price.regularAmount && { regularAmount: toEuroPrice(price.regularAmount) }),
  }
}

/** A GB category file as the NL prototype shows it: same bikes, euro prices. */
function forMarket(category: Category): Category {
  return {
    ...category,
    market: MARKET,
    currency: CURRENCY,
    products: category.products.map((product) => ({ ...product, price: euroPrice(product.price) })),
  }
}

// The generated files are plain JSON, so TypeScript widens `mode` to string and `tag` to a
// bare object — assert the shape the importer is contracted to write.
export const CATEGORIES: Category[] = (
  [
    roadBikes,
    mountainBikes,
    eBikes,
    crossAndGravelBikes,
    fitnessAndCityBikes,
    kidsBikes,
  ] as unknown as Category[]
).map(forMarket)

export const DEFAULT_CATEGORY_SLUG = 'road-bikes'

/** Mirrors the production URL structure, e.g. /nl/bikes/road-bikes. NL is the only market. */
export const CATEGORY_BASE_PATH = '/nl/bikes'

export function getCategory(slug: string): Category | undefined {
  return CATEGORIES.find((category) => category.slug === slug)
}
